#include "fates/graphics/cam_util.hpp"
#include "fates/detail/principal_camera_runtime.hpp"
nn::math::VEC3 CamUtil::CalcHitPos(const nn::math::VEC3& p){return fates::decomp_detail::CameraHitPos(p);} nn::math::VEC3 CamUtil::CalcHitArea(const nn::math::VEC3& a,const nn::math::VEC3& b){return fates::decomp_detail::CameraHitArea(a,b);} bool CamUtil::IsLongRange(){return fates::decomp_detail::CameraIsLongRange();} bool CamUtil::IsCloseRange(){return fates::decomp_detail::CameraIsCloseRange();} bool CamUtil::IsCutChanged(const nn::math::VEC3&a,const nn::math::VEC3&b){return fates::decomp_detail::CameraCutChanged(a,b);} 
void CamUtil::CalcTPSCamera(CameraParam*p,int s){if(p)fates::decomp_detail::CalcTPSCamera(*p,s);} void CamUtil::CalcBossCamera(CameraParam*p,const char*n){if(p)fates::decomp_detail::CalcBossCamera(*p,n);} void CamUtil::CalcHeadCamera(CameraParam*p,const nn::math::VEC3&a,const nn::math::VEC3&b){if(p)fates::decomp_detail::CalcHeadCamera(*p,a,b);} void CamUtil::CalcSideCamera(CameraParam*p,bool flip){if(p)CalcRotateCamera(p,"Side",GetUnitFlatDir(),flip);} void CamUtil::CalcFixedCamera(CameraParam*p,bool flip){if(p)fates::decomp_detail::CalcRotateCamera(*p,"Fixed",GetUnitRootDir(false),flip);} void CamUtil::CalcIntroCamera(CameraParam*p){if(p)fates::decomp_detail::CalcRotateCamera(*p,"Intro",GetUnitRootDir(false),false);} void CamUtil::CalcRotateCamera(CameraParam*p,const char*n,const nn::math::VEC3&d,bool f){if(p)fates::decomp_detail::CalcRotateCamera(*p,n,d,f);} void CamUtil::CalcTargetCamera(CameraParam*p,const char*n,const nn::math::VEC3&d,int u,bool r){if(p)fates::decomp_detail::CalcTargetCamera(*p,n,d,u,r);} 
nn::math::VEC3 CamUtil::GetUnitFlatDir(){return fates::decomp_detail::UnitFlatDir();} nn::math::VEC3 CamUtil::GetUnitHeadPos(int u){return fates::decomp_detail::UnitHeadPos(u);} nn::math::VEC3 CamUtil::GetUnitRootDir(bool e){return fates::decomp_detail::UnitRootDir(e);} const char* CamUtil::GetBossCameraName(){return fates::decomp_detail::BossCameraName();} nn::math::VEC3 CamUtil::GetUnitHeadRotate(int u){return fates::decomp_detail::UnitHeadRotate(u);} bool CamUtil::IsFlip(const nn::math::VEC3&a,const nn::math::VEC3&b){return a.x*b.x+a.y*b.y+a.z*b.z<0.0f;}
